-- Упражнения книги 19, глава 27 (Администрирование Linux). Файл строит автор-скрипт (не в репозитории); после правок можно редактировать и вручную.

INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 27, 'la27-wait-status', 0, 'c', 'Описание статуса завершения', 'Родитель получил статус от wait/waitpid и должен записать его в журнал человеческим языком. Напишите describe_status(status, buf, n): используйте только макросы WIFEXITED, WEXITSTATUS, WIFSIGNALED, WTERMSIG, WCOREDUMP, WIFSTOPPED, WSTOPSIG, WIFCONTINUED (сдвиги и маски вроде 0x7f или >> 8 драйвер считает нарушением). Формат: "exited with N", "killed by signal N", "killed by signal N (core dumped)", "stopped by signal N", "continued", иначе "unknown status". Строка помещается в buf размером n через snprintf (при нехватке места она обрезается), функция возвращает длину получившейся строки. Драйвер порождает настоящих детей: вышедших с кодами 0, 3 и 263 (родителю достаётся только младший байт), убитых сигналами, остановленного и продолженного, а статус со сброшенным образом памяти собирает вручную.', '#include <stdio.h>
#include <string.h>
#include <sys/wait.h>

/* Запишите в buf (размер n) описание статуса, который вернул wait/waitpid, и верните длину строки.
   Форматы: "exited with N", "killed by signal N", "killed by signal N (core dumped)",
   "stopped by signal N", "continued", иначе "unknown status". Только макросы W*. */
int describe_status(int status, char *buf, size_t n) {
    return -1;
}
', 'Проверяйте макросы по порядку: WIFEXITED, WIFSIGNALED, WIFSTOPPED, WIFCONTINUED. Длину возвращайте через strlen(buf), а не значением snprintf: оно считает несрезанную строку.', '{"driver": "/*__DRIVER__*/\n#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n#include <stdint.h>\n#include <stddef.h>\n#include <unistd.h>\n#include <fcntl.h>\n#include <errno.h>\n#include <signal.h>\n#include <sys/types.h>\n#include <sys/wait.h>\n#include <sys/mman.h>\n#include <sys/stat.h>\n#include <sys/ioctl.h>\n\nstatic void setup(void) { setvbuf(stdout, NULL, _IONBF, 0); }\n\nstatic int src_count(const char *pat) {\n    FILE *f = fopen(\"/sandbox/main.c\", \"r\");\n    static char buf[1 << 17];\n    size_t n = fread(buf, 1, sizeof buf - 1, f);\n    buf[n] = 0;\n    fclose(f);\n    char *mk = strstr(buf, \"/*__\" \"DRIVER__*/\");\n    if (mk) *mk = 0;\n    int c = 0;\n    for (char *p = buf; (p = strstr(p, pat)) != NULL; p += strlen(pat)) c++;\n    return c;\n}\n\n/* readable output: newlines become ''|'' */\nstatic void show(const char *tag, const char *s) {\n    printf(\"%s [\", tag);\n    for (; *s; s++) putchar(*s == ''\\n'' ? ''|'' : *s);\n    printf(\"]\\n\");\n}\n\nint main(void) {\n    setup();\n    char buf[80];\n    const char *names[] = {\"_exit(0)\", \"_exit(3)\", \"_exit(263)\", \"SIGTERM\", \"SIGKILL\"};\n    for (int k = 0; k < 5; k++) {\n        pid_t p = fork();\n        if (p == 0) {\n            if (k == 0) _exit(0);\n            if (k == 1) _exit(3);\n            if (k == 2) _exit(263);\n            if (k == 3) raise(SIGTERM);\n            if (k == 4) kill(getpid(), SIGKILL);\n            _exit(99);\n        }\n        int st = 0;\n        waitpid(p, &st, 0);\n        int r = describe_status(st, buf, sizeof buf);\n        printf(\"%-10s -> %s (%d)\\n\", names[k], buf, r);\n    }\n    /* a stopped and then continued child */\n    pid_t p = fork();\n    if (p == 0) { raise(SIGSTOP); _exit(0); }\n    int st = 0;\n    waitpid(p, &st, WUNTRACED);\n    int r = describe_status(st, buf, sizeof buf);\n    printf(\"%-10s -> %s (%d)\\n\", \"SIGSTOP\", buf, r);\n    kill(p, SIGCONT);\n    waitpid(p, &st, WCONTINUED);\n    r = describe_status(st, buf, sizeof buf);\n    printf(\"%-10s -> %s (%d)\\n\", \"SIGCONT\", buf, r);\n    kill(p, SIGKILL);\n    waitpid(p, &st, 0);\n    /* a status with the core-dump bit, built by hand (the Linux layout: signal in the low 7 bits, 0x80 = core) */\n    r = describe_status(SIGSEGV | 0x80, buf, sizeof buf);\n    printf(\"%-10s -> %s (%d)\\n\", \"SEGV+core\", buf, r);\n    char small[8];\n    r = describe_status(3 << 8, small, sizeof small);\n    printf(\"%-10s -> %s (%d)\\n\", \"short buf\", small, r);\n    printf(\"raw bit tricks: %s\\n\", src_count(\"0x\") + src_count(\">>\") + src_count(\"& 255\") ? \"used\" : \"none\");\n    return 0;\n}\n", "expected": ["_exit(0)   -> exited with 0 (13)", "_exit(3)   -> exited with 3 (13)", "_exit(263) -> exited with 7 (13)", "SIGTERM    -> killed by signal 15 (19)", "SIGKILL    -> killed by signal 9 (18)", "SIGSTOP    -> stopped by signal 19 (20)", "SIGCONT    -> continued (9)", "SEGV+core  -> killed by signal 11 (core dumped) (33)", "short buf  -> exited  (7)", "raw bit tricks: none"]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 27, 'la27-pipeline', 1, 'c', 'Конвейер из двух программ', 'Реализуйте на fork, pipe, dup2 и execvp то, что оболочка делает для «left | right». Функция run_pipeline(left, right, out, cap) создаёт два канала (один между программами, другой возвращает вывод родителю), порождает двух детей, ставит концы на дескрипторы 0 и 1, закрывает все лишние концы и запускает программы. Родитель читает вывод right до конца файла (в out помещается не больше cap-1 байт, остальное читается и выбрасывается, строка заканчивается нулём), ждёт обоих детей и возвращает код выхода right, 128 + номер сигнала, если right убит, или -1 при сбое pipe/fork. Не удавшийся exec даёт код 127 в ребёнке. Драйвер гоняет sort, tr, wc, несуществующие команды, большой вывод (seq на 20 000 строк), урезанный вывод и убитый сигналом процесс, а затем проверяет, что не осталось ни детей, ни утёкших дескрипторов. system() и popen() запрещены. Если забыть закрыть записывающий конец в родителе, тест зависнет на wc: читатель не получит EOF.', '#include <stdio.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <sys/types.h>
#include <sys/wait.h>

/* Выполните конвейер "left | right". left и right - массивы argv для execvp (с NULL в конце).
   Стандартный вывод right соберите в out (не больше cap-1 байт, строка заканчивается нулём; лишнее
   читайте и выбрасывайте). Верните код выхода right; если right убит сигналом, верните 128 + номер сигнала;
   при сбое pipe/fork верните -1. Если exec не удался, ребёнок выходит с кодом 127.
   Нельзя system() и popen(). Дождитесь обоих детей и не оставляйте открытых дескрипторов. */
int run_pipeline(char *const left[], char *const right[], char *out, size_t cap) {
    return -1;
}
', 'В ребёнке сначала dup2, потом close всех четырёх концов, потом execvp, а после него _exit(127). В родителе закройте a[0], a[1], b[1] до чтения из b[0].', '{"driver": "/*__DRIVER__*/\n#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n#include <stdint.h>\n#include <stddef.h>\n#include <unistd.h>\n#include <fcntl.h>\n#include <errno.h>\n#include <signal.h>\n#include <sys/types.h>\n#include <sys/wait.h>\n#include <sys/mman.h>\n#include <sys/stat.h>\n#include <sys/ioctl.h>\n\nstatic void setup(void) { setvbuf(stdout, NULL, _IONBF, 0); }\n\nstatic int src_count(const char *pat) {\n    FILE *f = fopen(\"/sandbox/main.c\", \"r\");\n    static char buf[1 << 17];\n    size_t n = fread(buf, 1, sizeof buf - 1, f);\n    buf[n] = 0;\n    fclose(f);\n    char *mk = strstr(buf, \"/*__\" \"DRIVER__*/\");\n    if (mk) *mk = 0;\n    int c = 0;\n    for (char *p = buf; (p = strstr(p, pat)) != NULL; p += strlen(pat)) c++;\n    return c;\n}\n\n/* readable output: newlines become ''|'' */\nstatic void show(const char *tag, const char *s) {\n    printf(\"%s [\", tag);\n    for (; *s; s++) putchar(*s == ''\\n'' ? ''|'' : *s);\n    printf(\"]\\n\");\n}\n\nstatic void run(const char *tag, char *const l[], char *const r[], size_t cap) {\n    char out[4096];\n    int before = dup(0);\n    close(before);\n    int st = run_pipeline(l, r, out, cap);\n    int after = dup(0);\n    close(after);\n    char head[96];\n    snprintf(head, sizeof head, \"%-8s status=%d fds=%s out=\", tag, st, before == after ? \"same\" : \"LEAK\");\n    show(head, out);\n}\n\nint main(void) {\n    setup();\n    signal(SIGPIPE, SIG_DFL);\n    char *a1[] = {\"printf\", \"b\\\\nc\\\\na\\\\n\", NULL}, *b1[] = {\"sort\", NULL};\n    run(\"sort\", a1, b1, 4096);\n    char *a2[] = {\"echo\", \"hello pipe\", NULL}, *b2[] = {\"tr\", \"a-z\", \"A-Z\", NULL};\n    run(\"upper\", a2, b2, 4096);\n    char *a3[] = {\"echo\", \"x\", NULL}, *b3[] = {\"no-such-command-zz\", NULL};\n    run(\"bad-right\", a3, b3, 4096);\n    char *a4[] = {\"no-such-command-zz\", NULL}, *b4[] = {\"wc\", \"-c\", NULL};\n    run(\"bad-left\", a4, b4, 4096);\n    char *a5[] = {\"echo\", \"x\", NULL}, *b5[] = {\"sh\", \"-c\", \"exit 5\", NULL};\n    run(\"exit5\", a5, b5, 4096);\n    char *a6[] = {\"seq\", \"1\", \"20000\", NULL}, *b6[] = {\"wc\", \"-l\", NULL};\n    run(\"big\", a6, b6, 4096);\n    char *a7[] = {\"seq\", \"1\", \"20\", NULL}, *b7[] = {\"cat\", NULL};\n    run(\"truncate\", a7, b7, 12);\n    char *a8[] = {\"echo\", \"x\", NULL}, *b8[] = {\"sh\", \"-c\", \"kill -9 $$\", NULL};\n    run(\"killed\", a8, b8, 4096);\n    printf(\"children left: %s\\n\", waitpid(-1, NULL, WNOHANG) == -1 && errno == ECHILD ? \"none\" : \"SOME\");\n    printf(\"shell shortcuts: %s\\n\", src_count(\"system(\") + src_count(\"popen(\") ? \"used\" : \"none\");\n    return 0;\n}\n", "expected": ["sort     status=0 fds=same out= [a|b|c|]", "upper    status=0 fds=same out= [HELLO PIPE|]", "bad-right status=127 fds=same out= []", "bad-left status=0 fds=same out= [0|]", "exit5    status=5 fds=same out= []", "big      status=0 fds=same out= [20000|]", "truncate status=0 fds=same out= [1|2|3|4|5|6]", "killed   status=137 fds=same out= []", "children left: none", "shell shortcuts: none"]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 27, 'la27-cloexec', 2, 'c', 'Что переживает exec', 'Дескриптор без флага FD_CLOEXEC достаётся новой программе после exec, с флагом закрывается. Напишите четыре функции. set_cloexec(fd, on) читает флаги дескриптора через fcntl(F_GETFD), включает или выключает FD_CLOEXEC и записывает через F_SETFD; 0 при успехе, -1 при ошибке (errno остаётся от fcntl, для плохого fd это EBADF). is_cloexec(fd) возвращает 1, 0 или -1. pipe_cloexec(fds) создаёт канал, оба конца которого сразу имеют флаг, одним вызовом pipe2 (так между pipe и fcntl не остаётся окна для чужого fork+exec в другой нити; драйвер проверит флаги обоих концов и то, что после exec их не видно). spawn_with_fd(argv, fd) делает fork и execv(argv[0], argv); в ребёнке перед exec нужно снять флаг у fd, чтобы ровно этот дескриптор пережил exec, а все остальные с флагом закрылись. Родитель ждёт ребёнка и возвращает его код выхода (127, если exec не удался). Флаг у fd в родителе после этого остаётся прежним: таблица дескрипторов ребёнка отдельная. Драйвер запускает настоящую оболочку и проверяет по /proc/self/fd, какие дескрипторы она видит.', '#define _GNU_SOURCE
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/types.h>
#include <sys/wait.h>

/* set_cloexec: включить (on != 0) или выключить флаг FD_CLOEXEC у fd, не трогая прочие флаги дескриптора.
   Вернуть 0, при ошибке -1 (errno от fcntl). */
int set_cloexec(int fd, int on) {
    return -1;
}

/* is_cloexec: 1, если флаг стоит, 0, если нет, -1 при ошибке. */
int is_cloexec(int fd) {
    return -1;
}

/* pipe_cloexec: создать канал, у которого ОБА конца сразу закрываются при exec (атомарно, одним вызовом). */
int pipe_cloexec(int fds[2]) {
    return -1;
}

/* spawn_with_fd: fork + execv(argv[0], argv); в ребёнке fd должен пережить exec (снимите флаг только
   в ребёнке), остальные дескрипторы с флагом закрываются. Родитель ждёт ребёнка и возвращает его код
   выхода; если exec не удался, ребёнок выходит с кодом 127; при сбое fork вернуть -1. */
int spawn_with_fd(char *const argv[], int fd) {
    return -1;
}
', 'set_cloexec: fl = fcntl(fd, F_GETFD); fl |= FD_CLOEXEC или fl &= ~FD_CLOEXEC; fcntl(fd, F_SETFD, fl). Для pipe2 нужен #define _GNU_SOURCE до включений, он уже есть в заготовке.', '{"driver": "/*__DRIVER__*/\n#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n#include <stdint.h>\n#include <stddef.h>\n#include <unistd.h>\n#include <fcntl.h>\n#include <errno.h>\n#include <signal.h>\n#include <sys/types.h>\n#include <sys/wait.h>\n#include <sys/mman.h>\n#include <sys/stat.h>\n#include <sys/ioctl.h>\n\nstatic void setup(void) { setvbuf(stdout, NULL, _IONBF, 0); }\n\nstatic int src_count(const char *pat) {\n    FILE *f = fopen(\"/sandbox/main.c\", \"r\");\n    static char buf[1 << 17];\n    size_t n = fread(buf, 1, sizeof buf - 1, f);\n    buf[n] = 0;\n    fclose(f);\n    char *mk = strstr(buf, \"/*__\" \"DRIVER__*/\");\n    if (mk) *mk = 0;\n    int c = 0;\n    for (char *p = buf; (p = strstr(p, pat)) != NULL; p += strlen(pat)) c++;\n    return c;\n}\n\n/* readable output: newlines become ''|'' */\nstatic void show(const char *tag, const char *s) {\n    printf(\"%s [\", tag);\n    for (; *s; s++) putchar(*s == ''\\n'' ? ''|'' : *s);\n    printf(\"]\\n\");\n}\n\n/* does a fresh shell started by exec see this descriptor? */\nstatic int exec_sees(int fd) {\n    char cmd[80];\n    snprintf(cmd, sizeof cmd, \"test -L /proc/self/fd/%d\", fd);\n    pid_t p = fork();\n    if (p == 0) {\n        execl(\"/bin/sh\", \"sh\", \"-c\", cmd, (char *)NULL);\n        _exit(127);\n    }\n    int st = 0;\n    waitpid(p, &st, 0);\n    return WIFEXITED(st) && WEXITSTATUS(st) == 0;\n}\n\nint main(void) {\n    setup();\n    int fd = open(\"/etc/hostname\", O_RDONLY);\n    if (fd < 0) fd = open(\"/etc/passwd\", O_RDONLY);\n    printf(\"fresh fd: cloexec=%d, exec sees it: %d\\n\", is_cloexec(fd), exec_sees(fd));\n    printf(\"set on: %d, cloexec=%d, exec sees it: %d\\n\", set_cloexec(fd, 1), is_cloexec(fd), exec_sees(fd));\n    printf(\"set off: %d, cloexec=%d, exec sees it: %d\\n\", set_cloexec(fd, 0), is_cloexec(fd), exec_sees(fd));\n    printf(\"set on again: %d\\n\", set_cloexec(fd, 1));\n    errno = 0;\n    int r1 = set_cloexec(-1, 1);\n    int e1 = errno;\n    errno = 0;\n    int r2 = is_cloexec(-1);\n    printf(\"bad fd: set=%d (%s), is=%d (%s)\\n\", r1, e1 == EBADF ? \"EBADF\" : \"?\", r2, errno == EBADF ? \"EBADF\" : \"?\");\n\n    int p[2];\n    printf(\"pipe_cloexec: %d\\n\", pipe_cloexec(p));\n    printf(\"pipe ends cloexec: %d %d, exec sees: %d %d\\n\", is_cloexec(p[0]), is_cloexec(p[1]), exec_sees(p[0]), exec_sees(p[1]));\n    if (write(p[1], \"ok\", 2) != 2) return 1;\n    char b[4] = {0};\n    if (read(p[0], b, 2) != 2) return 1;\n    printf(\"pipe works: %s\\n\", b);\n\n    /* fd stays close-on-exec in the parent; the child gets it, but not the pipe ends */\n    int other = open(\"/etc/passwd\", O_RDONLY | O_CLOEXEC);\n    char cmd[160];\n    snprintf(cmd, sizeof cmd, \"test -L /proc/self/fd/%d && test ! -L /proc/self/fd/%d && test ! -L /proc/self/fd/%d\", fd, other, p[0]);\n    char *argv[] = {\"/bin/sh\", \"-c\", cmd, NULL};\n    printf(\"spawn_with_fd: child status %d\\n\", spawn_with_fd(argv, fd));\n    printf(\"parent keeps flag: %d\\n\", is_cloexec(fd));\n    char *bad[] = {\"/no/such/program\", NULL};\n    printf(\"spawn bad program: %d\\n\", spawn_with_fd(bad, fd));\n    return 0;\n}\n", "expected": ["fresh fd: cloexec=0, exec sees it: 1", "set on: 0, cloexec=1, exec sees it: 0", "set off: 0, cloexec=0, exec sees it: 1", "set on again: 0", "bad fd: set=-1 (EBADF), is=-1 (EBADF)", "pipe_cloexec: 0", "pipe ends cloexec: 1 1, exec sees: 0 0", "pipe works: ok", "spawn_with_fd: child status 0", "parent keeps flag: 1", "spawn bad program: 127"]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 27, 'la27-parallel-sum', 3, 'c', 'Сумма силами дочерних процессов', 'Разделяемая память между родственными процессами - это mmap с MAP_SHARED | MAP_ANONYMOUS, сделанный до fork. Реализуйте parallel_sum(v, n, workers): создайте такое отображение на workers значений long, породите workers детей (ребёнок i считает срез [i*n/workers, (i+1)*n/workers) и записывает сумму в ячейку i, затем _exit(0)), дождитесь всех детей (wait), сложите ячейки, снимите отображение munmap и верните сумму. Если workers < 1, mmap или fork не удались либо какой-то ребёнок завершился не кодом 0, верните -1 (уже запущенных детей всё равно нужно дождаться). Потоки запрещены. Драйвер проверяет суммы для разных n и workers (включая workers больше n и n = 0), то, что входной массив не изменён, что не осталось неподобранных детей и что число отображений процесса вернулось к прежнему. Вариант с MAP_PRIVATE или обычным массивом вернёт нули: дети пишут в свои копии.', '#include <stdlib.h>
#include <unistd.h>
#include <sys/mman.h>
#include <sys/types.h>
#include <sys/wait.h>

/* Просуммируйте v[0..n) силами workers дочерних процессов: ребёнок i берёт срез [i*n/workers, (i+1)*n/workers),
   пишет свою частичную сумму в общую анонимную память и выходит через _exit(0). Родитель ждёт всех детей,
   складывает частичные суммы, освобождает отображение и возвращает итог.
   -1: workers < 1, сбой mmap/fork или ребёнок кончился не кодом 0. Потоков нет, только fork. */
long parallel_sum(const int *v, int n, int workers) {
    return -1;
}
', 'Вычисляйте границы среза в long, чтобы i*n не переполнило int. Дети используют _exit, а не exit: буфер stdio родителя им не нужен.', '{"driver": "/*__DRIVER__*/\n#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n#include <stdint.h>\n#include <stddef.h>\n#include <unistd.h>\n#include <fcntl.h>\n#include <errno.h>\n#include <signal.h>\n#include <sys/types.h>\n#include <sys/wait.h>\n#include <sys/mman.h>\n#include <sys/stat.h>\n#include <sys/ioctl.h>\n\nstatic void setup(void) { setvbuf(stdout, NULL, _IONBF, 0); }\n\nstatic int src_count(const char *pat) {\n    FILE *f = fopen(\"/sandbox/main.c\", \"r\");\n    static char buf[1 << 17];\n    size_t n = fread(buf, 1, sizeof buf - 1, f);\n    buf[n] = 0;\n    fclose(f);\n    char *mk = strstr(buf, \"/*__\" \"DRIVER__*/\");\n    if (mk) *mk = 0;\n    int c = 0;\n    for (char *p = buf; (p = strstr(p, pat)) != NULL; p += strlen(pat)) c++;\n    return c;\n}\n\n/* readable output: newlines become ''|'' */\nstatic void show(const char *tag, const char *s) {\n    printf(\"%s [\", tag);\n    for (; *s; s++) putchar(*s == ''\\n'' ? ''|'' : *s);\n    printf(\"]\\n\");\n}\n\nstatic int map_lines(void) {\n    static char buf[1 << 16];\n    int fd = open(\"/proc/self/maps\", O_RDONLY);\n    int n = (int)read(fd, buf, sizeof buf - 1), lines = 0;\n    close(fd);\n    for (int i = 0; i < n; i++) if (buf[i] == ''\\n'') lines++;\n    return lines;\n}\n\nstatic int vals[100000];\n\nint main(void) {\n    setup();\n    for (int i = 0; i < 1000; i++) vals[i] = i + 1;\n    int maps0 = map_lines();\n    printf(\"1..1000, 4 workers: %ld\\n\", parallel_sum(vals, 1000, 4));\n    printf(\"1..1000, 1 worker: %ld\\n\", parallel_sum(vals, 1000, 1));\n    printf(\"1..1000, 7 workers: %ld\\n\", parallel_sum(vals, 1000, 7));\n    printf(\"n=2, 5 workers: %ld\\n\", parallel_sum(vals, 2, 5));\n    printf(\"n=0, 3 workers: %ld\\n\", parallel_sum(vals, 0, 3));\n    printf(\"0 workers: %ld\\n\", parallel_sum(vals, 10, 0));\n    for (int i = 0; i < 100000; i++) vals[i] = i + 1;\n    printf(\"1..100000, 8 workers: %ld\\n\", parallel_sum(vals, 100000, 8));\n    printf(\"input untouched: %d %d\\n\", vals[0], vals[99999]);\n    printf(\"children left: %s\\n\", waitpid(-1, NULL, WNOHANG) == -1 && errno == ECHILD ? \"none\" : \"SOME\");\n    printf(\"mapping released: %s\\n\", map_lines() == maps0 ? \"yes\" : \"NO\");\n    printf(\"threads: %s\\n\", src_count(\"pthread\") ? \"used\" : \"none\");\n    return 0;\n}\n", "expected": ["1..1000, 4 workers: 500500", "1..1000, 1 worker: 500500", "1..1000, 7 workers: 500500", "n=2, 5 workers: 3", "n=0, 3 workers: 0", "0 workers: -1", "1..100000, 8 workers: 5000050000", "input untouched: 1 100000", "children left: none", "mapping released: yes", "threads: none"]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 27, 'la27-map-file', 4, 'c', 'Файл через mmap', 'Три функции, которые работают с файлом только через mmap (вызовы read, pread и fopen драйвер считает нарушением). count_byte(path, c) отображает файл PROT_READ | MAP_PRIVATE и считает вхождения байта c; пустой файл даёт 0 без вызова mmap (длина 0 для mmap - ошибка EINVAL), несуществующий файл -1. overwrite_at(path, off, s) открывает файл O_RDWR, отображает его MAP_SHARED, копирует s (без нуля) со смещения off, вызывает msync(MS_SYNC) и снимает отображение; если off + strlen(s) выходит за размер файла, ничего не менять и вернуть -1 (запись за концом файла через отображение вызвала бы SIGBUS или не изменила бы файл); 0 при успехе. byte_at(path, off) возвращает байт по смещению off, отображая только одну страницу: смещение для mmap нужно округлить вниз до кратного sysconf(_SC_PAGE_SIZE), иначе EINVAL. Если off за концом файла, верните -1. Драйвер пишет файл в 200000 байт, проверяет смещения до и после границы страницы и запись, пересекающую границу.', '#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <sys/types.h>

/* Работаем с файлом только через mmap: read/pread/fread запрещены.

   count_byte: сколько раз байт c встречается в файле (отображение PROT_READ, MAP_PRIVATE).
   -1, если файл не открылся или отображение не удалось; пустой файл даёт 0 (mmap с длиной 0 - ошибка).

   overwrite_at: записать строку s (без нуля) в файл со смещения off через MAP_SHARED, вызвать msync(MS_SYNC),
   снять отображение. Файл не растёт: если off + strlen(s) больше размера, ничего не менять и вернуть -1.
   0 при успехе.

   byte_at: значение байта (0..255) по смещению off, отображая только страницу, где он лежит: смещение mmap
   нужно округлить вниз до границы страницы (sysconf(_SC_PAGE_SIZE)). -1, если off за концом файла или при ошибке. */
long count_byte(const char *path, int c) {
    return -1;
}

int overwrite_at(const char *path, size_t off, const char *s) {
    return -1;
}

int byte_at(const char *path, off_t off) {
    return -1;
}
', 'Для byte_at: base = off - off % page; длина отображения (off - base) + 1; байт лежит по адресу m[off - base]. Размер файла берите через fstat.', '{"driver": "/*__DRIVER__*/\n#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n#include <stdint.h>\n#include <stddef.h>\n#include <unistd.h>\n#include <fcntl.h>\n#include <errno.h>\n#include <signal.h>\n#include <sys/types.h>\n#include <sys/wait.h>\n#include <sys/mman.h>\n#include <sys/stat.h>\n#include <sys/ioctl.h>\n\nstatic void setup(void) { setvbuf(stdout, NULL, _IONBF, 0); }\n\nstatic int src_count(const char *pat) {\n    FILE *f = fopen(\"/sandbox/main.c\", \"r\");\n    static char buf[1 << 17];\n    size_t n = fread(buf, 1, sizeof buf - 1, f);\n    buf[n] = 0;\n    fclose(f);\n    char *mk = strstr(buf, \"/*__\" \"DRIVER__*/\");\n    if (mk) *mk = 0;\n    int c = 0;\n    for (char *p = buf; (p = strstr(p, pat)) != NULL; p += strlen(pat)) c++;\n    return c;\n}\n\n/* readable output: newlines become ''|'' */\nstatic void show(const char *tag, const char *s) {\n    printf(\"%s [\", tag);\n    for (; *s; s++) putchar(*s == ''\\n'' ? ''|'' : *s);\n    printf(\"]\\n\");\n}\n\n#define SIZE 200000\n\nint main(void) {\n    setup();\n    char path[64], empty[64];\n    strcpy(path, \"/tmp/mfXXXXXX\");\n    int fd = mkstemp(path);\n    unsigned char *data = malloc(SIZE);\n    for (int i = 0; i < SIZE; i++) data[i] = (unsigned char)(i % 251);\n    if (write(fd, data, SIZE) != SIZE) return 1;\n    close(fd);\n    strcpy(empty, \"/tmp/mfeXXXXXX\");\n    close(mkstemp(empty));\n\n    printf(\"count 0: %ld\\n\", count_byte(path, 0));\n    printf(\"count 250: %ld\\n\", count_byte(path, 250));\n    printf(\"count 255: %ld\\n\", count_byte(path, 255));\n    printf(\"empty file: %ld\\n\", count_byte(empty, 1));\n    printf(\"missing file: %ld\\n\", count_byte(\"/tmp/no/such/file\", 1));\n\n    printf(\"byte_at 0: %d\\n\", byte_at(path, 0));\n    printf(\"byte_at 5000: %d\\n\", byte_at(path, 5000));\n    printf(\"byte_at 123456: %d\\n\", byte_at(path, 123456));\n    printf(\"byte_at last: %d\\n\", byte_at(path, SIZE - 1));\n    printf(\"byte_at past end: %d\\n\", byte_at(path, SIZE));\n    printf(\"byte_at in empty: %d\\n\", byte_at(empty, 0));\n\n    printf(\"overwrite ok: %d\\n\", overwrite_at(path, 4090, \"HELLO WORLD\"));\n    printf(\"overwrite last bytes: %d\\n\", overwrite_at(path, SIZE - 2, \"ZZ\"));\n    printf(\"overwrite past end: %d\\n\", overwrite_at(path, SIZE - 1, \"ZZ\"));\n    printf(\"overwrite far: %d\\n\", overwrite_at(path, SIZE + 100, \"Q\"));\n    printf(\"overwrite empty string: %d\\n\", overwrite_at(path, 10, \"\"));\n    printf(\"overwrite missing: %d\\n\", overwrite_at(\"/tmp/no/such/file\", 0, \"x\"));\n\n    fd = open(path, O_RDONLY);\n    char b[12] = {0};\n    if (pread(fd, b, 11, 4090) != 11) return 1;\n    unsigned char z[2];\n    if (pread(fd, z, 2, SIZE - 2) != 2) return 1;\n    struct stat st;\n    fstat(fd, &st);\n    close(fd);\n    printf(\"file now: %s %c%c, size %ld\\n\", b, z[0], z[1], (long)st.st_size);\n    printf(\"read-style calls: %s\\n\", src_count(\"read(\") + src_count(\"fopen(\") ? \"used\" : \"none\");\n    unlink(path);\n    unlink(empty);\n    return 0;\n}\n", "expected": ["count 0: 797", "count 250: 796", "count 255: 0", "empty file: 0", "missing file: -1", "byte_at 0: 0", "byte_at 5000: 231", "byte_at 123456: 215", "byte_at last: 203", "byte_at past end: -1", "byte_at in empty: -1", "overwrite ok: 0", "overwrite last bytes: 0", "overwrite past end: -1", "overwrite far: -1", "overwrite empty string: 0", "overwrite missing: -1", "file now: HELLO WORLD ZZ, size 200000", "read-style calls: none"]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 27, 'la27-ioctl-numbers', 5, 'c', 'Номер запроса ioctl вручную', 'Разберите номер запроса так, как это делает strace или внимательный читатель заголовка. Напишите ioc_encode(dir, type, nr, size), которая собирает число сдвигами и масками (nr в битах 0-7, type в 8-15, size в 16-29, dir в 30-31; формат общий для x86, ARM и RISC-V, на powerpc и некоторых других архитектурах он иной), ioc_decode(req, &dir, &type, &nr, &size) - обратную операцию, и ioc_macro(dir), которая называет макрос: 0 - "_IO", 1 - "_IOW", 2 - "_IOR", 3 - "_IOWR" (W и R считаются со стороны пользователя: _IOW значит, что ядро читает аргумент). Макросы _IOC*, _IO, _IOR, _IOW, _IOWR использовать нельзя; драйвер сам сверяет ваши числа с ними. Он разбирает настоящие запросы KVM (KVM_GET_API_VERSION, KVM_CREATE_VM, KVM_SET_USER_MEMORY_REGION, KVM_RUN и другие), два придуманных запроса и два старых запроса терминала (FIONREAD, TIOCGWINSZ), у которых размер и направление не закодированы.', '#include <sys/ioctl.h>

/* Соберите и разберите номер запроса ioctl вручную, сдвигами и масками, в общем для x86, ARM и RISC-V формате:
   биты 0..7 - номер команды nr, 8..15 - тип (символ драйвера), 16..29 - размер аргумента, 30..31 - направление.
   Направление: 0 нет данных (_IO), 1 запись, ядро читает у пользователя (_IOW), 2 чтение, ядро пишет
   пользователю (_IOR), 3 оба (_IOWR). Макросы _IOC*, _IO*, _IOR* использовать нельзя. */
unsigned long ioc_encode(int dir, int type, int nr, int size) {
    return 0;
}

void ioc_decode(unsigned long req, int *dir, int *type, int *nr, int *size) {
}

/* Имя макроса по направлению: "_IO", "_IOW", "_IOR", "_IOWR". */
const char *ioc_macro(int dir) {
    return "";
}
', 'Собирайте значение в unsigned long: dir=3 сдвигается в старшие биты 32-битного числа. Размер маскируйте 0x3fff, направление 3.', '{"driver": "/*__DRIVER__*/\n#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n#include <stdint.h>\n#include <stddef.h>\n#include <unistd.h>\n#include <fcntl.h>\n#include <errno.h>\n#include <signal.h>\n#include <sys/types.h>\n#include <sys/wait.h>\n#include <sys/mman.h>\n#include <sys/stat.h>\n#include <sys/ioctl.h>\n\nstatic void setup(void) { setvbuf(stdout, NULL, _IONBF, 0); }\n\nstatic int src_count(const char *pat) {\n    FILE *f = fopen(\"/sandbox/main.c\", \"r\");\n    static char buf[1 << 17];\n    size_t n = fread(buf, 1, sizeof buf - 1, f);\n    buf[n] = 0;\n    fclose(f);\n    char *mk = strstr(buf, \"/*__\" \"DRIVER__*/\");\n    if (mk) *mk = 0;\n    int c = 0;\n    for (char *p = buf; (p = strstr(p, pat)) != NULL; p += strlen(pat)) c++;\n    return c;\n}\n\n/* readable output: newlines become ''|'' */\nstatic void show(const char *tag, const char *s) {\n    printf(\"%s [\", tag);\n    for (; *s; s++) putchar(*s == ''\\n'' ? ''|'' : *s);\n    printf(\"]\\n\");\n}\n\n#include <linux/kvm.h>\n\nstruct pair { uint32_t a, b; };\n#define PAIR_SWAP _IOWR(''k'', 7, struct pair)\n#define DEMO_GET  _IOR(''E'', 1, int)\n\nstatic int bad;\n\nstatic void show_req(const char *name, unsigned long req) {\n    int d, t, n, s;\n    ioc_decode(req, &d, &t, &n, &s);\n    printf(\"%-26s 0x%08lx dir=%d type=0x%02x nr=%-3d size=%-2d %s\\n\", name, req, d, t, n, s, ioc_macro(d));\n    if (ioc_encode(d, t, n, s) != req) { printf(\"  encode mismatch\\n\"); bad++; }\n}\n\nint main(void) {\n    setup();\n    show_req(\"KVM_GET_API_VERSION\", KVM_GET_API_VERSION);\n    show_req(\"KVM_CREATE_VM\", KVM_CREATE_VM);\n    show_req(\"KVM_GET_VCPU_MMAP_SIZE\", KVM_GET_VCPU_MMAP_SIZE);\n    show_req(\"KVM_RUN\", KVM_RUN);\n    show_req(\"KVM_SET_USER_MEMORY_REGION\", KVM_SET_USER_MEMORY_REGION);\n    show_req(\"PAIR_SWAP\", PAIR_SWAP);\n    show_req(\"DEMO_GET\", DEMO_GET);\n    show_req(\"FIONREAD (old style)\", FIONREAD);\n    show_req(\"TIOCGWINSZ (old style)\", TIOCGWINSZ);\n    printf(\"encode vs macros: %s\\n\",\n           ioc_encode(2, ''E'', 1, sizeof(int)) == DEMO_GET && ioc_encode(1, 0xAE, 0x46, 32) == KVM_SET_USER_MEMORY_REGION &&\n           ioc_encode(0, 0xAE, 0, 0) == KVM_GET_API_VERSION ? \"equal\" : \"DIFFERENT\");\n    printf(\"mismatches: %d\\n\", bad);\n    printf(\"macros in source: %s\\n\", src_count(\"_IOC\") + src_count(\"_IO(\") + src_count(\"_IOR(\") + src_count(\"_IOW(\") + src_count(\"_IOWR(\") ? \"used\" : \"none\");\n    return 0;\n}\n", "expected": ["KVM_GET_API_VERSION        0x0000ae00 dir=0 type=0xae nr=0   size=0  _IO", "KVM_CREATE_VM              0x0000ae01 dir=0 type=0xae nr=1   size=0  _IO", "KVM_GET_VCPU_MMAP_SIZE     0x0000ae04 dir=0 type=0xae nr=4   size=0  _IO", "KVM_RUN                    0x0000ae80 dir=0 type=0xae nr=128 size=0  _IO", "KVM_SET_USER_MEMORY_REGION 0x4020ae46 dir=1 type=0xae nr=70  size=32 _IOW", "PAIR_SWAP                  0xc0086b07 dir=3 type=0x6b nr=7   size=8  _IOWR", "DEMO_GET                   0x80044501 dir=2 type=0x45 nr=1   size=4  _IOR", "FIONREAD (old style)       0x0000541b dir=0 type=0x54 nr=27  size=0  _IO", "TIOCGWINSZ (old style)     0x00005413 dir=0 type=0x54 nr=19  size=0  _IO", "encode vs macros: equal", "mismatches: 0", "macros in source: none"]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 27, 'la27-ticker-device', 6, 'c', 'Драйвер устройства через ioctl', 'Устройство /dev/ticker - счётчик, управляемый только запросами ioctl; в песочнице его нет, поэтому драйвер подменяет open, ioctl и close моделью, а вы пишете настоящий код с настоящими вызовами (запросы определены в заготовке, менять их нельзя). ticker_run(path, step, n) открывает path, проверяет версию интерфейса через TICK_GET_VERSION (нужна 2, иначе ошибка EPROTO), задаёт шаг через TICK_SET_STEP, n раз вызывает TICK_ADVANCE (аргумента нет) и возвращает значение TICK_GET_TOTAL. При любой ошибке верните -errno причины, закрыв дескриптор. Тонкость: успешный close вправе оставить в errno что угодно (модель ставит EIO), поэтому errno нужно сохранить до закрытия. Модель отвечает как ядро: EBUSY на занятом устройстве, EINVAL на шаг 0 и меньше, ENOENT на незнакомый путь, а версию 1 возвращает у /dev/ticker-old. Драйвер печатает результат и сколько раз открыли, закрыли и продвинули счётчик: утечки дескриптора видны сразу.', '#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>

/* Модель устройства-счётчика /dev/ticker (в песочнице его нет: драйвер подменяет open, ioctl и close).
   Запросы НЕ менять: */
#define TICK_GET_VERSION _IOR(''t'', 1, int)   /* записывает версию интерфейса в *arg */
#define TICK_SET_STEP    _IOW(''t'', 2, int)   /* шаг счётчика берётся из *arg, должен быть > 0, иначе EINVAL */
#define TICK_ADVANCE     _IO(''t'', 3)         /* прибавляет шаг к счётчику, аргумента нет */
#define TICK_GET_TOTAL   _IOR(''t'', 4, long)  /* записывает значение счётчика в *arg */

/* ticker_run: открыть path (O_RDWR), проверить, что версия интерфейса равна 2 (иначе ошибка EPROTO),
   задать шаг step, вызвать TICK_ADVANCE n раз, прочитать TICK_GET_TOTAL и вернуть его.
   При любой ошибке верните -errno причины (ошибка open, ioctl или EPROTO), но сначала закройте
   дескриптор: close не должен подменить причину. */
long ticker_run(const char *path, int step, int n) {
    return -1;
}
', 'Заведите переменную err: в ветке ошибки err = errno сразу после неудавшегося вызова, close(fd) один раз в конце, затем return err ? -err : total.', '{"driver": "/*__DRIVER__*/\n#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n#include <stdint.h>\n#include <stddef.h>\n#include <unistd.h>\n#include <fcntl.h>\n#include <errno.h>\n#include <signal.h>\n#include <sys/types.h>\n#include <sys/wait.h>\n#include <sys/mman.h>\n#include <sys/stat.h>\n#include <sys/ioctl.h>\n\nstatic void setup(void) { setvbuf(stdout, NULL, _IONBF, 0); }\n\nstatic int src_count(const char *pat) {\n    FILE *f = fopen(\"/sandbox/main.c\", \"r\");\n    static char buf[1 << 17];\n    size_t n = fread(buf, 1, sizeof buf - 1, f);\n    buf[n] = 0;\n    fclose(f);\n    char *mk = strstr(buf, \"/*__\" \"DRIVER__*/\");\n    if (mk) *mk = 0;\n    int c = 0;\n    for (char *p = buf; (p = strstr(p, pat)) != NULL; p += strlen(pat)) c++;\n    return c;\n}\n\n/* readable output: newlines become ''|'' */\nstatic void show(const char *tag, const char *s) {\n    printf(\"%s [\", tag);\n    for (; *s; s++) putchar(*s == ''\\n'' ? ''|'' : *s);\n    printf(\"]\\n\");\n}\n\n#include <stdarg.h>\n\n#define TFD 100\nstatic int t_open, t_closed, t_advance, t_is_open, t_version, t_step;\nstatic long t_total;\n\nint __real_open(const char *path, int flags, ...);\nint __real_ioctl(int fd, unsigned long req, ...);\nint __real_close(int fd);\n\nint __wrap_open(const char *path, int flags, ...) {\n    int old = strcmp(path, \"/dev/ticker-old\") == 0;\n    if (strcmp(path, \"/dev/ticker-busy\") == 0) { errno = EBUSY; return -1; }\n    if (strcmp(path, \"/dev/ticker\") == 0 || old) {\n        t_open++;\n        t_is_open = 1;\n        t_version = old ? 1 : 2;\n        t_step = 1;\n        t_total = 0;\n        return TFD;\n    }\n    return __real_open(path, flags, 0);\n}\n\nint __wrap_ioctl(int fd, unsigned long req, ...) {\n    va_list ap;\n    va_start(ap, req);\n    void *arg = req == TICK_ADVANCE ? NULL : va_arg(ap, void *);\n    va_end(ap);\n    if (fd != TFD) return __real_ioctl(fd, req, arg);\n    if (!t_is_open) { errno = EBADF; return -1; }\n    if (req == TICK_GET_VERSION) { *(int *)arg = t_version; return 0; }\n    if (req == TICK_SET_STEP) {\n        int s = *(int *)arg;\n        if (s <= 0) { errno = EINVAL; return -1; }\n        t_step = s;\n        return 0;\n    }\n    if (req == TICK_ADVANCE) { t_total += t_step; t_advance++; return 0; }\n    if (req == TICK_GET_TOTAL) { *(long *)arg = t_total; return 0; }\n    errno = ENOTTY;\n    return -1;\n}\n\nint __wrap_close(int fd) {\n    if (fd != TFD) return __real_close(fd);\n    if (!t_is_open) { errno = EBADF; return -1; }\n    t_is_open = 0;\n    t_closed++;\n    errno = EIO;   /* a successful call may leave any errno behind */\n    return 0;\n}\n\nstatic const char *ename(long r) {\n    switch (-r) {\n    case ENOENT: return \"ENOENT\";\n    case EBUSY: return \"EBUSY\";\n    case EINVAL: return \"EINVAL\";\n    case EPROTO: return \"EPROTO\";\n    case ENOTTY: return \"ENOTTY\";\n    case EIO: return \"EIO\";\n    default: return \"\";\n    }\n}\n\nstatic void run(const char *tag, const char *path, int step, int n) {\n    t_open = t_closed = t_advance = t_is_open = 0;\n    long r = ticker_run(path, step, n);\n    printf(\"%-9s -> %ld%s%s | opened=%d closed=%d advances=%d%s\\n\", tag, r, r < 0 ? \" \" : \"\", r < 0 ? ename(r) : \"\", t_open, t_closed, t_advance,\n           t_is_open ? \" LEAK\" : \"\");\n}\n\nint main(void) {\n    setup();\n    run(\"normal\", \"/dev/ticker\", 5, 4);\n    run(\"no-steps\", \"/dev/ticker\", 3, 0);\n    run(\"step-0\", \"/dev/ticker\", 0, 4);\n    run(\"old\", \"/dev/ticker-old\", 5, 4);\n    run(\"busy\", \"/dev/ticker-busy\", 5, 4);\n    run(\"missing\", \"/no/such/dev\", 5, 4);\n    run(\"again\", \"/dev/ticker\", 2, 10);\n    return 0;\n}\n", "expected": ["normal    -> 20 | opened=1 closed=1 advances=4", "no-steps  -> 0 | opened=1 closed=1 advances=0", "step-0    -> -22 EINVAL | opened=1 closed=1 advances=0", "old       -> -71 EPROTO | opened=1 closed=1 advances=0", "busy      -> -16 EBUSY | opened=0 closed=0 advances=0", "missing   -> -2 ENOENT | opened=0 closed=0 advances=0", "again     -> 20 | opened=1 closed=1 advances=10"], "flags": "-std=gnu11 -O1 -Wall -Wl,--wrap=open,--wrap=ioctl,--wrap=close"}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 27, 'la27-ioctl-probes', 7, 'c', 'FIONREAD и TIOCGWINSZ', 'Две настоящие команды ioctl, которые встречаются в программах постоянно. pending_bytes(fd) спрашивает у канала через FIONREAD (аргумент - указатель на int), сколько байт уже можно прочитать; число или -errno. read_available(fd, buf, cap) читает не больше cap байт, но только готовые: если в канале пусто, возвращает 0 и не вызывает блокирующий read (иначе тест завис бы на пустом канале); число прочитанных байт или -errno. terminal_width(fd) спрашивает ширину терминала через TIOCGWINSZ (struct winsize, поле ws_col): если fd не терминал (ошибка ENOTTY) или ширина равна 0, возвращает 80, любая другая ошибка - это -errno. Драйвер использует настоящий канал, настоящий /dev/null, плохой дескриптор и подменённый через --wrap=ioctl «терминал» размером 24 на 132 (а ещё один с нулевой шириной).', '#include <errno.h>
#include <unistd.h>
#include <sys/ioctl.h>

/* pending_bytes: сколько непрочитанных байт лежит в канале fd (запрос FIONREAD, аргумент - int *).
   Верните число или -errno при ошибке.

   read_available: прочитать из fd не больше cap байт, но только то, что уже есть: если в канале пусто,
   верните 0, НЕ вызывая блокирующий read. Вернуть число прочитанных байт или -errno.

   terminal_width: ширина терминала fd (запрос TIOCGWINSZ, struct winsize, поле ws_col). Если fd не терминал
   (ошибка ENOTTY) или ширина равна 0, верните 80. Любая другая ошибка - -errno. */
int pending_bytes(int fd) {
    return -1;
}

long read_available(int fd, char *buf, size_t cap) {
    return -1;
}

int terminal_width(int fd) {
    return -1;
}
', 'pending_bytes: int n; ioctl(fd, FIONREAD, &n). Сохраняйте errno сразу после ioctl, прежде чем вызывать что-либо ещё.', '{"driver": "/*__DRIVER__*/\n#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n#include <stdint.h>\n#include <stddef.h>\n#include <unistd.h>\n#include <fcntl.h>\n#include <errno.h>\n#include <signal.h>\n#include <sys/types.h>\n#include <sys/wait.h>\n#include <sys/mman.h>\n#include <sys/stat.h>\n#include <sys/ioctl.h>\n\nstatic void setup(void) { setvbuf(stdout, NULL, _IONBF, 0); }\n\nstatic int src_count(const char *pat) {\n    FILE *f = fopen(\"/sandbox/main.c\", \"r\");\n    static char buf[1 << 17];\n    size_t n = fread(buf, 1, sizeof buf - 1, f);\n    buf[n] = 0;\n    fclose(f);\n    char *mk = strstr(buf, \"/*__\" \"DRIVER__*/\");\n    if (mk) *mk = 0;\n    int c = 0;\n    for (char *p = buf; (p = strstr(p, pat)) != NULL; p += strlen(pat)) c++;\n    return c;\n}\n\n/* readable output: newlines become ''|'' */\nstatic void show(const char *tag, const char *s) {\n    printf(\"%s [\", tag);\n    for (; *s; s++) putchar(*s == ''\\n'' ? ''|'' : *s);\n    printf(\"]\\n\");\n}\n\n#include <stdarg.h>\n\n#define TTY_BIG 100\n#define TTY_ZERO 101\n\nint __real_ioctl(int fd, unsigned long req, ...);\n\nint __wrap_ioctl(int fd, unsigned long req, ...) {\n    va_list ap;\n    va_start(ap, req);\n    void *arg = va_arg(ap, void *);\n    va_end(ap);\n    if (fd != TTY_BIG && fd != TTY_ZERO) return __real_ioctl(fd, req, arg);\n    if (req == TIOCGWINSZ) {\n        struct winsize *w = arg;\n        w->ws_row = 24;\n        w->ws_col = fd == TTY_BIG ? 132 : 0;\n        w->ws_xpixel = w->ws_ypixel = 0;\n        return 0;\n    }\n    errno = ENOTTY;\n    return -1;\n}\n\nint main(void) {\n    setup();\n    int p[2];\n    if (pipe(p) != 0) return 1;\n    printf(\"empty pipe: pending=%d\\n\", pending_bytes(p[0]));\n    char buf[16] = {0};\n    printf(\"empty pipe: read_available=%ld\\n\", read_available(p[0], buf, sizeof buf));\n    if (write(p[1], \"hello\", 5) != 5) return 1;\n    printf(\"after write 5: pending=%d, from write end: pending=%d\\n\", pending_bytes(p[0]), pending_bytes(p[1]));\n    long r = read_available(p[0], buf, 3);\n    printf(\"read_available(cap 3)=%ld [%.3s], pending=%d\\n\", r, buf, pending_bytes(p[0]));\n    memset(buf, 0, sizeof buf);\n    r = read_available(p[0], buf, sizeof buf);\n    printf(\"read_available(cap 16)=%ld [%s], pending=%d\\n\", r, buf, pending_bytes(p[0]));\n    printf(\"again on empty: %ld\\n\", read_available(p[0], buf, sizeof buf));\n    printf(\"bad fd: pending=%d, read_available=%ld, width=%d\\n\", pending_bytes(999), read_available(999, buf, 4), terminal_width(999));\n    printf(\"pending on fake tty: %d\\n\", pending_bytes(TTY_BIG));\n    printf(\"width: pipe=%d, tty=%d, zero-size tty=%d\\n\", terminal_width(p[0]), terminal_width(TTY_BIG), terminal_width(TTY_ZERO));\n    int nul = open(\"/dev/null\", O_RDONLY);\n    printf(\"width of /dev/null: %d\\n\", terminal_width(nul));\n    return 0;\n}\n", "expected": ["empty pipe: pending=0", "empty pipe: read_available=0", "after write 5: pending=5, from write end: pending=5", "read_available(cap 3)=3 [hel], pending=2", "read_available(cap 16)=2 [lo], pending=0", "again on empty: 0", "bad fd: pending=-9, read_available=-9, width=-9", "pending on fake tty: -25", "width: pipe=80, tty=132, zero-size tty=80", "width of /dev/null: 80"], "flags": "-std=gnu11 -O1 -Wall -Wl,--wrap=ioctl"}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 27, 'la27-fork-tree', 8, 'func', 'Дерево процессов из strace -f', 'text - вывод strace -f ... для команды, root - номер её главного процесса. Строки главного процесса идут без приставки, остальные начинаются с "[pid N]" (число может быть дополнено пробелами). Напишите функцию fork_tree(text, root): верните список кортежей (pid, parent, exec, end), отсортированный по pid, для главного процесса и всех процессов, которые появились в тексте. parent - pid создателя (главный процесс: None); его знает вызов clone, clone3, fork или vfork, вернувший этот pid положительным числом (`= 3001`; результат -1 никого не создаёт). exec - путь последнего УСПЕШНОГО (результат 0) вызова execve или execveat (у execveat путь - второй аргумент после AT_FDCWD), иначе None; неудавшиеся попытки (ENOENT и т. п.) не считаются. end - "exit N" для строки "+++ exited with N +++" и "signal NAME" для "+++ killed by NAME ... +++" (пометку о core dump игнорируйте), иначе None. Вызовы бывают разорваны: "... <unfinished ...>" в одной строке и "<... name resumed>...) = N" в другой (с приставкой того же процесса, между ними могут быть строки других); путь execve при этом виден только в первой половине, результат только во второй. Строки "--- SIGCHLD ... ---" и прочие системные вызовы игнорируйте.', 'def fork_tree(text, root):
    pass
', 'Для каждой строки определите процесс (приставка или root) и тело. Для разорванного вызова запомните имя и путь по pid; на строке resumed достаньте их обратно. Результат - последнее ") = число" в строке.', '{"func": "fork_tree", "tests": [{"args": ["execve(\"/bin/sh\", [\"sh\", \"-c\", \"ls | wc -l\"], 0x7ffd5e0c8a98 /* 24 vars */) = 0\nbrk(NULL)                               = 0x55d0c6c5b000\npipe2([3, 4], 0)                        = 0\nclone(child_stack=NULL, flags=CLONE_CHILD_CLEARTID|CLONE_CHILD_SETTID|SIGCHLD, child_tidptr=0x7f2b3c1e2a10) = 3001\n[pid  3001] dup2(4, 1)                  = 1\n[pid  3001] execve(\"/bin/ls\", [\"ls\"], 0x55d0c6c5d1a8 /* 24 vars */) = 0\nclone(child_stack=NULL, flags=CLONE_CHILD_CLEARTID|CLONE_CHILD_SETTID|SIGCHLD, child_tidptr=0x7f2b3c1e2a10) = 3002\n[pid  3002] dup2(3, 0)                  = 0\n[pid  3002] execve(\"/usr/bin/wc\", [\"wc\", \"-l\"], 0x55d0c6c5d1a8 /* 24 vars */) = 0\n[pid  3001] +++ exited with 0 +++\n[pid  3002] +++ exited with 0 +++\n--- SIGCHLD {si_signo=SIGCHLD, si_code=CLD_EXITED, si_pid=3001, si_uid=1000, si_status=0, si_utime=0, si_stime=0} ---\nwait4(-1, [{WIFEXITED(s) && WEXITSTATUS(s) == 0}], 0, NULL) = 3001\n+++ exited with 0 +++\n", 3000], "expected": [{"__tuple__": [3000, null, "/bin/sh", "exit 0"]}, {"__tuple__": [3001, 3000, "/bin/ls", "exit 0"]}, {"__tuple__": [3002, 3000, "/usr/bin/wc", "exit 0"]}]}, {"args": ["[pid  4100] execve(\"/usr/bin/make\", [\"make\", \"all\"], 0x7ffc1e2b8f08 /* 31 vars */) = 0\n[pid  4100] clone(child_stack=NULL, flags=CLONE_CHILD_CLEARTID|CLONE_CHILD_SETTID|SIGCHLD, child_tidptr=0x7f6d1a3f4a10) <unfinished ...>\n[pid  4101] execve(\"/usr/local/bin/cc\", [\"cc\", \"-c\", \"a.c\"], 0x55a8e3b26f20 /* 31 vars */) = -1 ENOENT (No such file or directory)\n[pid  4100] <... clone resumed>, child_tidptr=0x7f6d1a3f4a10) = 4101\n[pid  4101] execve(\"/usr/bin/cc\", [\"cc\", \"-c\", \"a.c\"], 0x55a8e3b26f20 /* 31 vars */) <unfinished ...>\n[pid  4101] <... execve resumed>)       = 0\n[pid  4101] clone(child_stack=NULL, flags=CLONE_CHILD_CLEARTID|CLONE_CHILD_SETTID|SIGCHLD, child_tidptr=0x7f1c2e5b3a10) = 4102\n[pid  4102] execve(\"/usr/lib/gcc/x86_64-linux-gnu/13/cc1\", [\"cc1\", \"a.c\"], 0x55a8e3b26f20 /* 31 vars */) = 0\n[pid  4102] +++ killed by SIGSEGV (core dumped) +++\n[pid  4101] --- SIGCHLD {si_signo=SIGCHLD, si_code=CLD_DUMPED, si_pid=4102, si_uid=1000, si_status=SIGSEGV, si_utime=0, si_stime=0} ---\n[pid  4101] wait4(4102, [{WIFSIGNALED(s) && WTERMSIG(s) == SIGSEGV && WCOREDUMP(s)}], 0, NULL) = 4102\n[pid  4101] +++ exited with 1 +++\n[pid  4100] --- SIGCHLD {si_signo=SIGCHLD, si_code=CLD_EXITED, si_pid=4101, si_uid=1000, si_status=1, si_utime=0, si_stime=0} ---\n[pid  4100] wait4(4101, [{WIFEXITED(s) && WEXITSTATUS(s) == 1}], 0, NULL) = 4101\n[pid  4100] +++ exited with 2 +++\n", 4100], "expected": [{"__tuple__": [4100, null, "/usr/bin/make", "exit 2"]}, {"__tuple__": [4101, 4100, "/usr/bin/cc", "exit 1"]}, {"__tuple__": [4102, 4101, "/usr/lib/gcc/x86_64-linux-gnu/13/cc1", "signal SIGSEGV"]}]}, {"args": ["vfork(child_stack=NULL)                 = 612\nfork()                                  = 613\nclone(child_stack=NULL, flags=CLONE_CHILD_CLEARTID|CLONE_CHILD_SETTID|SIGCHLD, child_tidptr=0x7f0a1b2c3d10) = -1 EAGAIN (Resource temporarily unavailable)\n[pid   613] clone3({flags=CLONE_VM|CLONE_VFORK, exit_signal=SIGCHLD, stack=0x7f4d2c000000, stack_size=0x9000}, 88) = 614\n[pid   614] execve(\"/bin/true\", [\"true\"], 0x7ffe92c1a1e8 /* 12 vars */) = 0\n[pid   614] +++ exited with 0 +++\n[pid   613] +++ exited with 0 +++\n[pid   612] execveat(AT_FDCWD, \"/usr/bin/env\", [\"env\"], 0x7ffe92c1a1e8 /* 12 vars */, 0) = 0\n[pid   612] +++ killed by SIGTERM +++\n", 611], "expected": [{"__tuple__": [611, null, null, null]}, {"__tuple__": [612, 611, "/usr/bin/env", "signal SIGTERM"]}, {"__tuple__": [613, 611, null, "exit 0"]}, {"__tuple__": [614, 613, "/bin/true", "exit 0"]}]}, {"args": ["execve(\"/usr/bin/sleep\", [\"sleep\", \"5\"], 0x7ffd3a1b7f98 /* 20 vars */) = 0\nnanosleep({tv_sec=5, tv_nsec=0}, 0x7ffd3a1b7e90) = 0\n+++ exited with 0 +++\n", 77], "expected": [{"__tuple__": [77, null, "/usr/bin/sleep", "exit 0"]}]}, {"args": ["[pid 20017] execve(\"/bin/bash\", [\"bash\", \"-c\", \"sleep 100 &\"], 0x7ffe3b4a22c8 /* 22 vars */) = 0\n[pid 20017] clone(child_stack=NULL, flags=CLONE_CHILD_CLEARTID|CLONE_CHILD_SETTID|SIGCHLD, child_tidptr=0x7fbe4c8b3a10) = 20018\n[pid 20018] execve(\"/bin/sleep\", [\"sleep\", \"100\"], 0x55f2d18a3010 /* 22 vars */) = 0\n[pid 20017] +++ exited with 0 +++\n", 20017], "expected": [{"__tuple__": [20017, null, "/bin/bash", "exit 0"]}, {"__tuple__": [20018, 20017, "/bin/sleep", null]}]}, {"args": ["execve(\"/usr/sbin/sshd\", [\"sshd\", \"-D\"], 0x7ffe1cb1a3f8 /* 15 vars */) = 0\nclone(child_stack=NULL, flags=CLONE_CHILD_CLEARTID|CLONE_CHILD_SETTID|SIGCHLD, child_tidptr=0x7f93c61a1a10) = 901\nclone(child_stack=NULL, flags=CLONE_CHILD_CLEARTID|CLONE_CHILD_SETTID|SIGCHLD, child_tidptr=0x7f93c61a1a10) = 902\n[pid   901] clone(child_stack=NULL, flags=CLONE_CHILD_CLEARTID|CLONE_CHILD_SETTID|SIGCHLD, child_tidptr=0x7f93c61a1a10) = 903\n[pid   903] execve(\"/bin/bash\", [\"-bash\"], 0x55d3a2e0b1c0 /* 14 vars */) = 0\n[pid   903] execve(\"/usr/bin/vim\", [\"vim\", \"notes.txt\"], 0x55d3a2e0b1c0 /* 14 vars */) = 0\n[pid   903] +++ exited with 130 +++\n[pid   902] execve(\"/nonexistent\", [\"x\"], 0x55d3a2e0b1c0 /* 14 vars */) = -1 ENOENT (No such file or directory)\n[pid   902] +++ exited with 255 +++\n", 900], "expected": [{"__tuple__": [900, null, "/usr/sbin/sshd", null]}, {"__tuple__": [901, 900, null, null]}, {"__tuple__": [902, 900, null, "exit 255"]}, {"__tuple__": [903, 901, "/usr/bin/vim", "exit 130"]}]}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 27, 'la27-find-zombies', 9, 'func', 'Родители, которые не вызывают wait', 'text - вывод ps -eo pid,ppid,stat,args (или с заголовком COMMAND вместо ARGS). Столбцы разделены пробелами; первый - pid, второй - ppid, третий - состояние, остальная часть строки - команда (она может содержать пробелы). Зомби - процесс, состояние которого начинается с Z (Z, Z+, Zl и т. п.). Напишите функцию find_zombies(text): верните список кортежей (ppid, [pid зомби по возрастанию], команда родителя), по одному на каждого родителя, у которого есть хотя бы один зомби, отсортированный по ppid. Команду родителя берите из его строки в тексте; если родителя в тексте нет, это "?". Строки, которые начинаются не с двух чисел (заголовок), пропускайте.', 'def find_zombies(text):
    pass
', 'line.split(None, 3) даёт pid, ppid, состояние и остаток-команду. Соберите словарь «ppid → список зомби» и словарь «pid → команда».', '{"func": "find_zombies", "tests": [{"args": ["    PID    PPID STAT COMMAND\n      1       0 Ss   /sbin/init\n    412       1 Ss   /usr/sbin/sshd -D\n   1520       1 Ssl  /usr/bin/python3 /usr/bin/vdsmd\n   1688    1520 Z    [lvs] <defunct>\n   1702    1520 Z    [multipath] <defunct>\n   1710    1520 S    /usr/bin/python3 /usr/libexec/vdsm/supervdsmd\n   2204     412 Ss   sshd: admin [priv]\n   2231    2204 S    sshd: admin@pts/0\n   2232    2231 Ss+  -bash\n"], "expected": [{"__tuple__": [1520, [1688, 1702], "/usr/bin/python3 /usr/bin/vdsmd"]}]}, {"args": ["  PID  PPID STAT ARGS\n    1     0 Ss   /usr/lib/systemd/systemd --system\n  777     1 Ss   /usr/sbin/crond -n\n  901   777 Z    [backup.sh] <defunct>\n  955     1 Z    [oldjob] <defunct>\n  960   901 S    sleep 3\n  961   777 Z+   [sh] <defunct>\n  962   777 Zl   [worker] <defunct>\n"], "expected": [{"__tuple__": [1, [955], "/usr/lib/systemd/systemd --system"]}, {"__tuple__": [777, [901, 961, 962], "/usr/sbin/crond -n"]}]}, {"args": ["    PID    PPID STAT COMMAND\n      1       0 Ss   /sbin/init\n   3000       1 S    /usr/bin/sleep 600\n   3001    3000 S    /bin/true\n"], "expected": []}, {"args": ["    PID    PPID STAT COMMAND\n   5100    5099 Z    [gone-parent-child] <defunct>\n   5102    5099 Z    [x] <defunct>\n   5200       1 S<   /usr/bin/ntpd\n"], "expected": [{"__tuple__": [5099, [5100, 5102], "?"]}]}, {"args": [""], "expected": []}]}');
